import json

def parse_pkg_list(filename):
    with open(filename) as f:
        data = json.load(f)
    results = {}
    for proj in data.get('projects', []):
        pname = proj['path'].rsplit('/',1)[-1].rsplit('\\\\',1)[-1]
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                results.setdefault(pname, {})[pkg['id']] = pkg['resolvedVersion']
    return results

baseline = parse_pkg_list('baseline-packages.json')
after = parse_pkg_list('after-cpm-packages.json')

print('=== BASELINE ===')
for p, pkgs in sorted(baseline.items()):
    for pkg, ver in sorted(pkgs.items()):
        print(f'  {p}: {pkg} {ver}')

print()
print('=== AFTER CPM ===')
for p, pkgs in sorted(after.items()):
    for pkg, ver in sorted(pkgs.items()):
        print(f'  {p}: {pkg} {ver}')

print()
print('=== CHANGES ===')
for p in sorted(set(list(baseline.keys()) + list(after.keys()))):
    for pkg in sorted(set(list(baseline.get(p,{}).keys()) + list(after.get(p,{}).keys()))):
        bv = baseline.get(p,{}).get(pkg)
        av = after.get(p,{}).get(pkg)
        if bv != av:
            print(f'  {p}: {pkg} {bv} -> {av}')
"

